// Pixel medal for an achievement (art generated by backend/gen_badges.py).
export const AchievementBadge = ({ id, size = 40, locked = false, className = "", title }) => (
  <img src={`/art/badges/${id}.png`} alt={title || ""} title={title} width={size} height={size} draggable="false"
    className={`ach-badge ${locked ? "ach-badge-locked" : ""} ${className}`} data-testid={`badge-${id}`} />
);
